import type { Metadata } from "next";
import { SITE } from "@/data/site";

/** Generated by app/opengraph-image.tsx (trailing slash matches the site's URL style). */
const OG_IMAGE = "/opengraph-image/";

type Title = string | { absolute: string };

/** One place to build per-page metadata so every page gets canonical + Open Graph + Twitter tags. */
export function pageMeta({ title, description, path }: { title: Title; description: string; path: string }): Metadata {
  const ogTitle = typeof title === "string" ? `${title} | ${SITE.name}` : title.absolute;
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: SITE.name,
      locale: "en_US",
      title: ogTitle,
      description,
      url: path,
      images: [{ url: OG_IMAGE, width: 1200, height: 630, alt: "Stoneholdt Partners: we buy homes for luxury redevelopment" }],
    },
    twitter: { card: "summary_large_image", title: ogTitle, description, images: [OG_IMAGE] },
  };
}
